const CACHE='qubi-v6';
const SHELL=['/','/index.html','/styles.css','/app.js','/manifest.webmanifest','/assets/qubi-mascot.png','/assets/qubi-home.png','/assets/qubi-work.png','/assets/qubi-personal.png','/assets/icon-192.png','/assets/icon-512.png','/assets/sound-gentle.mp3','/assets/sound-bright.mp3'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.pathname.startsWith('/api/')||url.pathname.startsWith('/auth/'))return;if(request.mode==='navigate'){event.respondWith(fetch(request).then(response=>{const copy=response.clone();caches.open(CACHE).then(cache=>cache.put('/index.html',copy));return response}).catch(()=>caches.match('/index.html')));return}event.respondWith(caches.match(request).then(cached=>cached||fetch(request).then(response=>{if(response.ok&&url.origin===location.origin){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(request,copy))}return response}))) });
self.addEventListener('push',event=>{let data={title:'Qubi emlékeztető',body:'Egy küldetésed hamarosan kezdődik.',url:'/'};try{data={...data,...event.data.json()}}catch{}event.waitUntil(self.registration.showNotification(data.title,{body:data.body,icon:'/assets/icon-192.png',badge:'/assets/icon-192.png',tag:data.tag,vibrate:[180,80,180],silent:false,data:{url:data.url}}))});
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(list=>{const existing=list.find(client=>new URL(client.url).origin===location.origin);return existing?existing.focus():clients.openWindow(event.notification.data?.url||'/')}))});
